#[inline]
unsafe fn IS_INTRESOURCE(value: PCIDLIST_ABSOLUTE) -> BOOL {
    ((value as usize) >> 16 == 0) as BOOL
}

unsafe fn append_wide(dst: LPWSTR, capacity: usize, used: &mut usize, src: LPCWSTR) -> HRESULT {
    let mut src = src;
    while !src.is_null() && *src != 0 {
        if *used + 1 >= capacity {
            if capacity != 0 {
                *dst.add(capacity - 1) = 0;
            }
            return STRSAFE_E_INSUFFICIENT_BUFFER;
        }
        *dst.add(*used) = *src;
        *used += 1;
        src = src.add(1);
    }
    S_OK
}

unsafe fn StringCchPrintfW(
    dst: LPWSTR,
    capacity: usize,
    _format: LPCWSTR,
    first: LPCWSTR,
    second: LPCWSTR,
    third: LPCWSTR,
) -> HRESULT {
    if dst.is_null() || capacity == 0 {
        return STRSAFE_E_INSUFFICIENT_BUFFER;
    }
    let mut used = 0;
    for source in [first, CPP_COM_WSTR_BACKSLASH.as_ptr(), second, third] {
        let hr = append_wide(dst, capacity, &mut used, source);
        if hr < 0 {
            return hr;
        }
    }
    *dst.add(used) = 0;
    S_OK
}

unsafe fn StringCchCopyW(dst: LPWSTR, capacity: usize, src: LPCWSTR) -> HRESULT {
    if dst.is_null() || capacity == 0 {
        return STRSAFE_E_INSUFFICIENT_BUFFER;
    }
    let mut used = 0;
    let hr = append_wide(dst, capacity, &mut used, src);
    if hr >= 0 {
        *dst.add(used) = 0;
    }
    hr
}

static CPP_COM_WSTR_BACKSLASH: [WCHAR; 2] = [b'\\' as WCHAR, 0];

